def high(grade,track):
    for subj,items in common.items():
        for i,(topic,q,a,b,c,d,ans,exp) in enumerate(items,1):
            add(grade,track,subj,subj,f'بخش {i}',topic,q,a,b,c,d,ans,exp)
    for subj,items in tracks.get(track,{}).items():
        for i,(topic,q,a,b,c,d,ans,exp) in enumerate(items,1):
            book=f'{subj} {grade}'
            add(grade,track,subj,book,f'بخش {i}',topic,q,a,b,c,d,ans,exp)

for g in ['چهارم','پنجم','ششم','هفتم','هشتم','نهم']:
    middle(g)
for g in ['دهم','یازدهم','دوازدهم']:
    for t in ['تجربی','ریاضی','انسانی']:
        high(g,t)

# add a compact set of کنکور-style original questions for each high-school track; no verbatim reproduction of copyrighted exams.
for track, subj in [('تجربی','زیست‌شناسی'),('تجربی','شیمی'),('تجربی','فیزیک'),('تجربی','ریاضی'),('ریاضی','ریاضی'),('ریاضی','فیزیک'),('ریاضی','شیمی'),('انسانی','ریاضی و آمار'),('انسانی','اقتصاد'),('انسانی','جامعه‌شناسی')]:
    for year in ['1400','1401','1402','1403','1404','1405']:
        if subj=='ریاضی' and track=='تجربی':
            q='اگر تابع f(x)=x²-2x باشد، کمینه تابع در کدام x رخ می‌دهد؟'
            opts=['0','1','2','-1']; ans='B'; exp='f(x)=(x-1)²-1 است، پس کمینه در x=1 رخ می‌دهد.'
        elif subj=='فیزیک':
            q='جسمی با سرعت ثابت روی خط راست حرکت می‌کند. برآیند نیروی وارد بر آن در حالت ایده‌آل چقدر است؟'
            opts=['صفر','ثابت و غیرصفر','متغیر','نامشخص']; ans='A'; exp='سرعت ثابت یعنی شتاب صفر و در نتیجه برآیند نیرو صفر است.'
        elif subj=='شیمی':
            q='در یک واکنش اکسایش-کاهش، گونه‌ای که الکترون می‌گیرد چه نام دارد؟'
            opts=['عامل کاهنده','عامل اکسنده','محصول خنثی','کاتالیزگر']; ans='B'; exp='گونه‌ای که الکترون می‌گیرد کاهش می‌یابد و عامل اکسنده است.'
        elif subj=='زیست‌شناسی':
            q='کدام گزینه بهترین توصیف برای نقش آنزیم‌ها در سلول است؟'
            opts=['افزایش انرژی فعال‌سازی','کاهش انرژی فعال‌سازی','مصرف دائمی در واکنش','تبدیل شدن به DNA']; ans='B'; exp='آنزیم‌ها با کاهش انرژی فعال‌سازی سرعت واکنش را افزایش می‌دهند.'
        elif subj=='اقتصاد':
            q='اگر قیمت یک کالا افزایش یابد و سایر شرایط ثابت باشد، در مدل ساده تقاضا چه تغییری می‌کند؟'
            opts=['افزایش','کاهش','همیشه ثابت','دو برابر']; ans='B'; exp='طبق قانون تقاضا، با افزایش قیمت مقدار تقاضا معمولاً کاهش می‌یابد.'
        elif subj=='جامعه‌شناسی':
            q='کدام مورد نمونه‌ای از هنجار اجتماعی است؟'
            opts=['قانون فیزیک','رعایت نوبت در صف','جرم اتمی','دمای جوش آب']; ans='B'; exp='هنجارها قواعد و انتظارات رفتاری جامعه‌اند.'
        else:
            q='اگر میانگین سه عدد 12 باشد، مجموع آن سه عدد چند است؟'
            opts=['12','24','36','48']; ans='C'; exp='مجموع=میانگین×تعداد=12×3=36.'
        add('دوازدهم',track,subj,f'{subj} دوازدهم','کنکورمحور',f'سبک کنکور {year}',q,*opts,ans,exp,'سخت',f'سؤال تألیفی هم‌سبک کنکور {year}')
        rows[-1]['source_type']='konkur_style'; rows[-1]['source_year']=year

# dedupe by identity
seen=set(); out=[]
for r in rows:
    key=(r['grade'],r['track'],r['subject'],r['topic'],r['question'])
    if key not in seen:
        seen.add(key); out.append(r)
rows=out
fields=['grade','track','subject','book','chapter','topic','subtopic','difficulty','question','option_a','option_b','option_c','option_d','correct_option','explanation','source','source_type','source_year']
